\title{Path-Minimality of Positive $p$-Energies for Connected Bipartite Graphs}
\author{Aristotle}
\date{2026-07-03}

\begin{document}

\begin{abstract}
For a finite simple graph $G$ we study the \emph{positive $p$-energy}
$\Ep(G) = \sum_{\lambda > 0} \lambda^{p}$, the sum of the positive adjacency
eigenvalues each raised to a real exponent $p$, together with its mirror quantity
the negative $p$-energy $\Em(G) = \sum_{\lambda < 0} (-\lambda)^{p}$. Our central
structural result isolates the algebraic mechanism behind an identity long observed
for special families: whenever a real spectrum is antisymmetric under index
reflection --- $\lambda_{n-1-k} = -\lambda_k$ --- its positive and negative
$p$-energies coincide for every real $p$. This reflection antisymmetry is precisely
the spectral signature of bipartiteness, giving the \emph{Bipartite Balance Theorem}:
$\Ep(G) = \Em(G)$ for all bipartite $G$ and all $p$. Specializing to the path graph
$P_n$, whose spectrum is $\lambda_k = 2\cos((k+1)\pi/(n+1))$, we prove the exact
evaluation $E_2^{+}(P_n) = n-1$ via a roots-of-unity cosine sum, and we prove the
combinatorial core of path-minimality at $p=2$: every connected graph on $n$ vertices
has at least $n-1$ edges. Since $E_2^{+}(G) = |E(G)|$ for bipartite $G$, this yields
$E_2^{+}(G) \ge E_2^{+}(P_n)$ for connected bipartite $G$, with the path attaining the
minimum. We close by formulating the full $p \ge 2$ minimality conjecture as a
spectral majorization problem.
\end{abstract}

\maketitle

\section{Introduction}

The \emph{energy} of a graph, introduced in mathematical chemistry, is the sum of the
absolute values of its adjacency eigenvalues; it approximates the total
$\pi$-electron energy of conjugated hydrocarbons. A natural generalization replaces
absolute value by a power law: for a real exponent $p$, split the spectrum into its
positive and negative parts and sum the $p$-th powers separately. The positive
$p$-energy $\Ep$ isolates the contribution of the positive eigenvalues.

We answer, at $p=2$, the extremal question \emph{which connected graph minimizes
$\Ep$?} and identify the reusable structural principle governing the whole family. The
extremal answer is the path graph $P_n$. The structural principle is that the balance
$\Ep = \Em$ is a property of any \emph{reflection-antisymmetric} real spectrum, of
which bipartite spectra are the archetype.

\medskip
\noindent\textbf{Contributions.}
\begin{enumerate}[leftmargin=2em]
  \item Abstract bipartite balance (Theorem~\ref{thm:balance}): reflection
        antisymmetry implies $\Ep = \Em$ for all $p$.
  \item Path balance (Corollary~\ref{cor:pathbalance}): $\Ep(P_n) = \Em(P_n)$.
  \item Exact evaluation (Theorem~\ref{thm:eval}): $E_2^{+}(P_n) = n-1$.
  \item Combinatorial minimality (Theorem~\ref{thm:edges},
        Corollary~\ref{cor:min}): connected graphs have $\ge n-1$ edges, whence
        $E_2^{+}(G) \ge E_2^{+}(P_n)$ for connected bipartite $G$.
\end{enumerate}

\section{Definitions}

Throughout, $G$ is a finite simple graph on $\{1,\dots,n\}$ with symmetric $0/1$
adjacency matrix $A(G)$ and real \emph{adjacency spectrum}
$\lambda_0, \dots, \lambda_{n-1}$.

\begin{definition}[Positive and negative $p$-energy]
For a real exponent $p$,
\[
\Ep(G) = \sum_{k:\ \lambda_k > 0} \lambda_k^{\,p},
\qquad
\Em(G) = \sum_{k:\ \lambda_k < 0} (-\lambda_k)^{\,p},
\]
where terms with a non-positive base contribute $0$.
\end{definition}

\begin{definition}[Path spectrum]
The adjacency spectrum of the path graph $P_n$ is
\[
\lambda_k = 2\cos\!\left(\frac{(k+1)\pi}{n+1}\right), \qquad k = 0,1,\dots,n-1.
\]
Each $\lambda_k \in (-2,2)$ and the values strictly decrease in $k$.
\end{definition}

\begin{definition}[Reflection antisymmetry]
A finite real sequence $f(0),\dots,f(n-1)$ is \emph{antisymmetric under index
reflection} if $f(n-1-k) = -f(k)$ for all $0 \le k < n$.
\end{definition}

\begin{remark}
A graph is bipartite iff its spectrum is symmetric about $0$. Ordered
monotonically, this symmetry is exactly reflection antisymmetry; thus ``bipartite''
and ``reflection-antisymmetric spectrum'' are two views of one phenomenon.
\end{remark}

\section{Abstract Bipartite Balance}

\begin{theorem}[Abstract bipartite balance]\label{thm:balance}
Let $n \in \mathbb{N}$, let $p \in \mathbb{R}$, and let $f:\{0,\dots,n-1\}\to\mathbb{R}$
satisfy $f(n-1-k) = -f(k)$ for all $0 \le k < n$. Then
\[
\sum_{k=0}^{n-1} \big[f(k) > 0\big]\,f(k)^p
=
\sum_{k=0}^{n-1} \big[f(k) < 0\big]\,(-f(k))^p .
\]
\end{theorem}

\begin{proof}
Apply the reflection reindexing $k \mapsto n-1-k$ to the left sum, a bijection of the
range:
\[
\sum_{k=0}^{n-1} \big[f(k) > 0\big]\,f(k)^p
= \sum_{k=0}^{n-1} \big[f(n-1-k) > 0\big]\,f(n-1-k)^p .
\]
By hypothesis $f(n-1-k) = -f(k)$, so the reindexed term equals
$\big[-f(k) > 0\big]\,(-f(k))^p = \big[f(k) < 0\big]\,(-f(k))^p$, the $k$-th term of
the right sum. A termwise case-split on the sign of $f(k)$ (the zero case contributing
$0$ on both sides) gives equality term by term.
\end{proof}

The proof uses no property beyond antisymmetry and holds for every real $p$
simultaneously; it is the reusable structural core of the paper.

\begin{corollary}[Path balance]\label{cor:pathbalance}
For every $n$ and every real $p$, $\Ep(P_n) = \Em(P_n)$.
\end{corollary}

\begin{proof}
Using $\cos(\pi-\theta) = -\cos\theta$,
\[
\lambda_{n-1-k}
= 2\cos\!\left(\frac{(n-k)\pi}{n+1}\right)
= 2\cos\!\left(\pi - \frac{(k+1)\pi}{n+1}\right)
= -\lambda_k .
\]
Thus $f(k)=\lambda_k$ satisfies Theorem~\ref{thm:balance}, giving the claim.
\end{proof}

\begin{remark}[Non-vacuity]
The triangle $K_3$ has spectrum $\{2,-1,-1\}$, which is not reflection-antisymmetric;
here $E_p^{+}(K_3) = 2^p \ne 2 = E_p^{-}(K_3)$ for all $p \ne 1$. Balance genuinely
requires the symmetry.
\end{remark}

\section{Exact Evaluation at $p=2$}

\begin{lemma}[Trace identity]\label{lem:trace}
For any simple graph $G$ on $n$ vertices, $\sum_{k=0}^{n-1}\lambda_k^2 = 2\,|E(G)|$.
\end{lemma}

\begin{proof}
The sum is $\tr(A(G)^2)$, whose diagonal entries are the vertex degrees; by the
handshake lemma $\sum_v \deg(v) = 2|E(G)|$.
\end{proof}

\begin{theorem}[Exact path evaluation]\label{thm:eval}
For every $n \ge 1$, $\; E_2^{+}(P_n) = n-1$.
\end{theorem}

\begin{proof}
With $\cos^2\theta = \tfrac12(1+\cos 2\theta)$,
\[
\sum_{k=0}^{n-1}\lambda_k^2
= \sum_{k=0}^{n-1} 4\cos^2\!\left(\frac{(k+1)\pi}{n+1}\right)
= 2n + 2\sum_{j=1}^{n} \cos\!\left(\frac{2\pi j}{n+1}\right).
\]
Since $\sum_{j=0}^{n}\cos(2\pi j/(n+1)) = \operatorname{Re}\sum_{j=0}^{n} e^{2\pi i
j/(n+1)} = 0$, removing the $j=0$ term gives $\sum_{j=1}^{n}\cos(2\pi j/(n+1)) = -1$,
so $\sum_k \lambda_k^2 = 2(n-1)$. By Corollary~\ref{cor:pathbalance} at $p=2$ the
positive and negative $2$-energies are equal and exhaust the sum of squares, hence
$E_2^{+}(P_n) = \tfrac12\cdot 2(n-1) = n-1$.
\end{proof}

\begin{proposition}[$p=2$ energy is edge count for bipartite graphs]\label{prop:edgecount}
For a bipartite graph $G$, $E_2^{+}(G) = |E(G)|$.
\end{proposition}

\begin{proof}
Bipartiteness gives $E_2^{+}(G) = E_2^{-}(G)$; these partition
$\sum_k \lambda_k^2 = 2|E(G)|$ (Lemma~\ref{lem:trace}), so each equals $|E(G)|$.
\end{proof}

\section{Combinatorial Minimality at $p=2$}

\begin{theorem}[Connectivity edge bound]\label{thm:edges}
Every connected simple graph $G$ on $n$ vertices satisfies $|E(G)| \ge n-1$.
\end{theorem}

\begin{proof}
A connected graph contains a spanning tree $T$ on all $n$ vertices; a tree on $n$
vertices has exactly $n-1$ edges (induction on leaves). Since $T \subseteq G$,
$|E(G)| \ge n-1$.
\end{proof}

\begin{corollary}[Path-minimality at $p=2$]\label{cor:min}
For every connected bipartite graph $G$ on $n$ vertices,
$E_2^{+}(G) \ge E_2^{+}(P_n) = n-1$, with equality for the path.
\end{corollary}

\begin{proof}
By Proposition~\ref{prop:edgecount}, $E_2^{+}(G) = |E(G)|$; by
Theorem~\ref{thm:edges}, $|E(G)| \ge n-1$; by Theorem~\ref{thm:eval},
$n-1 = E_2^{+}(P_n)$. The path is a tree, so $|E(P_n)| = n-1$.
\end{proof}

\section{Applications and Context}

Positive $p$-energies interpolate between combinatorial and spectral invariants: at
$p=2$ they reduce (for bipartite graphs) to edge counts; for larger $p$ they weight
the dominant eigenvalues. Extremal questions connect to mathematical chemistry
(alternant hydrocarbons carry exactly the pairing symmetry of
Theorem~\ref{thm:balance}), to network science (sparse connected structures as
baselines), and to spectral majorization (the framework for the open $p \ge 2$
conjecture). The Bipartite Balance Theorem also stands alone: any real vector
symmetric under an order-reversing sign involution has equal positive and negative
power-sums.

\section{Discussion and Future Work}

The exponent $p=2$ is fully resolved; the balance $\Ep=\Em$ holds for all real $p$.
What remains is to lift the comparison to all $p \ge 2$.

\begin{conjecture}[Full path-minimality]
For every connected bipartite $G$ on $n$ vertices and every real $p \ge 2$,
$\Ep(G) \ge \Ep(P_n)$, with equality iff $G$ is the path.
\end{conjecture}
The path has minimal spectral radius and its remaining positive eigenvalues fill
$(0,2)$ as slowly as connectivity permits; convexity of $x \mapsto x^p$ for $p \ge 2$
should convert this into an energy inequality via majorization of the positive
spectrum.

\begin{conjecture}[Uniqueness and runner-up]
For every $p > 2$ the path is the unique minimizer, and the second-smallest value is
attained by a ``broom'' (path with a relocated pendant edge).
\end{conjecture}

\begin{conjecture}[$p$-energy isoperimetric sandwich]
For bipartite graphs with fixed part sizes $a,b$, positive $p$-energy is minimized by
the balanced caterpillar and maximized by $K_{a,b}$, for all $p \ge 2$.
\end{conjecture}

\section{Conclusion}

The balance of positive and negative $p$-energies is a universal consequence of
reflection antisymmetry --- the spectral fingerprint of bipartiteness. At $p=2$ this
yields path-minimality of positive energy among connected bipartite graphs, with the
exact value $E_2^{+}(P_n) = n-1$. Extending minimality to all $p \ge 2$ is now sharply
posed as a spectral majorization problem.

\end{document}

